@RestController
public class SessionController {

    @PostMapping("/session/restore")
    public ResponseEntity<String> restore(@RequestBody byte[] body) throws Exception {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(body))) {
            SessionState state = (SessionState) in.readObject();
            return ResponseEntity.ok(state.getUserId());
        }
    }
}
